"""Emit internal/rich/colordata.go from the installed rich (oracle venv)."""
import sys
from rich.color import ANSI_COLOR_NAMES, STANDARD_PALETTE, EIGHT_BIT_PALETTE
from rich.default_styles import DEFAULT_STYLES
import rich

out = []
w = out.append
w("// Code generated by work-PYF/richgen.py from rich %s; DO NOT EDIT." % getattr(rich, "__version__", ""))
w("")
w("package rich")
w("")
w("// ansiColorNames is rich.color.ANSI_COLOR_NAMES.")
w("var ansiColorNames = map[string]int{")
for k, v in ANSI_COLOR_NAMES.items():
    w('\t"%s": %d,' % (k, v))
w("}")
w("")
w("// eightBitPalette is rich.color.EIGHT_BIT_PALETTE.")
w("var eightBitPalette = [256][3]int{")
for c in EIGHT_BIT_PALETTE._colors:
    w("\t{%d, %d, %d}," % tuple(c))
w("}")
w("")
w("// standardPalette is rich.color.STANDARD_PALETTE.")
w("var standardPalette = [][3]int{")
for c in STANDARD_PALETTE._colors:
    w("\t{%d, %d, %d}," % tuple(c))
w("}")
w("")
w("// defaultStyles is rich.default_styles.DEFAULT_STYLES (as definitions).")
w("var defaultStyles = map[string]string{")
for k, v in DEFAULT_STYLES.items():
    s = str(v)
    w('\t%s: %s,' % (repr_go(k) if False else '"' + k + '"', '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'))
w("}")
open(sys.argv[1], "w").write("\n".join(out) + "\n")
